:root {
  --ink: #2C5F68;
  --muted: #6B7280;
  --accent: #D97742;
  --paper: #F5F5F7;
  --line: #E5E7EB;
  --warm: #FFF7ED;
}

.chapter-scope {
  font-family: system-ui, -apple-system, sans-serif;
  color: var(--ink);
  background: var(--paper);
  padding: 2rem 1.5rem;
  line-height: 1.6;
  max-width: 900px;
  margin: 0 auto;
}

.chapter-header h2 {
  font-size: 1.75rem;
  margin-bottom: 0.5rem;
  color: var(--ink);
}

.lead {
  font-size: 1.1rem;
  color: var(--muted);
  max-width: 700px;
  margin-bottom: 2rem;
}

.interaction-workbench {
  display: grid;
  grid-template-columns: 1fr 1.2fr;
  gap: 2rem;
  background: #fff;
  padding: 1.5rem;
  border-radius: 8px;
  border: 1px solid var(--line);
  margin-bottom: 2rem;
}

@media (max-width: 768px) {
  .interaction-workbench {
    grid-template-columns: 1fr;
  }
}

.control-panel h3, .visualization-panel h4 {
  font-size: 1rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--muted);
  margin-bottom: 1rem;
  border-bottom: 1px solid var(--line);
  padding-bottom: 0.5rem;
}

.radio-group {
  display: flex;
  flex-direction: column;
  gap: 1rem;
  margin-bottom: 2rem;
}

.radio-card {
  display: flex;
  align-items: flex-start;
  padding: 1rem;
  border: 1px solid var(--line);
  border-radius: 6px;
  cursor: pointer;
  transition: all 0.2s;
  background: #fff;
}

.radio-card:hover {
  border-color: var(--ink);
  background: #f9fafb;
}

.radio-card.active {
  border-color: var(--ink);
  background: #f0f9ff;
  box-shadow: 0 0 0 1px var(--ink);
}

.radio-card input {
  margin-right: 1rem;
  margin-top: 0.25rem;
}

.card-title {
  font-weight: 600;
  display: block;
  color: var(--ink);
}

.card-desc {
  font-size: 0.875rem;
  color: var(--muted);
  display: block;
  margin-top: 0.25rem;
}

.formula-display {
  background: var(--warm);
  padding: 1rem;
  border-radius: 6px;
  border-left: 4px solid var(--accent);
}

.equation-box {
  font-family: 'Times New Roman', serif;
  font-size: 1.25rem;
  text-align: center;
  margin: 1rem 0;
  font-style: italic;
}

.variable {
  font-weight: bold;
  color: var(--ink);
}

.formula-note {
  font-size: 0.875rem;
  color: var(--muted);
  text-align: center;
  margin-top: 0.5rem;
}

.gdp-bar-chart {
  margin-bottom: 2rem;
}

.chart-container {
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
}

.bar-group {
  display: flex;
  align-items: center;
  gap: 1rem;
}

.bar-label {
  width: 140px;
  font-size: 0.9rem;
  color: var(--ink);
  font-weight: 500;
}

.bar-track {
  flex-grow: 1;
  height: 32px;
  background: #f3f4f6;
  border-radius: 4px;
  position: relative;
  overflow: hidden;
}

.bar-fill {
  height: 100%;
  background: var(--ink);
  border-radius: 4px;
  transition: width 0.8s cubic-bezier(0.4, 0, 0.2, 1);
  display: flex;
  align-items: center;
  justify-content: flex-end;
  padding-right: 0.5rem;
}

.revised-fill {
  background: #9CA3AF;
}

.strong-fill {
  background: var(--accent);
}

.bar-value {
  position: absolute;
  right: 0.5rem;
  top: 50%;
  transform: translateY(-50%);
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--ink);
  z-index: 2;
}

.welfare-alert {
  background: #fff;
  border: 1px solid var(--line);
  border-radius: 6px;
  padding: 1rem;
}

.warning-text {
  color: #991B1B;
  background: #FEF2F2;
  padding: 0.75rem;
  border-radius: 4px;
  border-left: 3px solid #EF4444;
  font-size: 0.9rem;
}

.citation-ref {
  font-size: 0.75rem;
  color: var(--muted);
  margin-top: 0.5rem;
  font-style: italic;
}

.evidence-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
  gap: 1.5rem;
}

.evidence-card {
  background: #fff;
  padding: 1.25rem;
  border-radius: 6px;
  border: 1px solid var(--line);
}

.evidence-card h4 {
  font-size: 1rem;
  color: var(--ink);
  margin-bottom: 0.75rem;
}

.evidence-card p {
  font-size: 0.9rem;
  color: #374151;
  margin-bottom: 1rem;
}

.source-btn {
  background: transparent;
  border: 1px solid var(--line);
  color: var(--ink);
  padding: 0.25rem 0.75rem;
  border-radius: 4px;
  font-size: 0.75rem;
  cursor: pointer;
  transition: all 0.2s;
  margin-right: 0.5rem;
}

.source-btn:hover {
  background: var(--ink);
  color: #fff;
  border-color: var(--ink);
}

@media (prefers-reduced-motion: reduce) {
  .bar-fill {
    transition: none;
  }
}
