javascript:
(function() {
  const scope = document.querySelector('#investment-response');
  if (!scope) return;

  const radios = scope.querySelectorAll('input[name="scenario"]');
  const cards = scope.querySelectorAll('.radio-card');
  const baselineFill = scope.querySelector('.baseline-fill');
  const revisedFill = scope.querySelector('.revised-fill');
  const strongFill = scope.querySelector('.strong-fill');
  const strongGroup = scope.querySelector('.strong-response-group');
  const baselineMsg = scope.querySelector('.baseline-msg');
  const strongMsg = scope.querySelector('.strong-msg');
  const sourceBtns = scope.querySelectorAll('.source-btn');

  // Constants from paper
  const CAPITAL_SHARE = 0.43;
  const MULTIPLIER = 1 / (1 - CAPITAL_SHARE); // ~1.75
  const TFP_BASELINE = 0.66;
  const TFP_REVISED = 0.53;
  const GDP_STRONG_UPPER = 1.56;

  function formatPercent(val) {
    return val.toFixed(2) + '%';
  }

  function updateUI(scenario) {
    // Update cards
    cards.forEach(card => {
      if (card.dataset.scenario === scenario) {
        card.classList.add('active');
      } else {
        card.classList.remove('active');
      }
    });

    // Calculate GDP
    const gdpBaseline = TFP_BASELINE * MULTIPLIER;
    const gdpRevised = TFP_REVISED * MULTIPLIER;

    // Animate bars
    requestAnimationFrame(() => {
      baselineFill.style.width = (gdpBaseline / 2 * 100) + '%';
      baselineFill.parentElement.querySelector('.bar-value').textContent = formatPercent(gdpBaseline);

      revisedFill.style.width = (gdpRevised / 2 * 100) + '%';
      revisedFill.parentElement.querySelector('.bar-value').textContent = formatPercent(gdpRevised);

      if (scenario === 'strong') {
        strongGroup.style.opacity = '1';
        strongFill.style.width = (GDP_STRONG_UPPER / 2 * 100) + '%';
        strongFill.parentElement.querySelector('.bar-value').textContent = formatPercent(GDP_STRONG_UPPER);

        baselineMsg.style.display = 'none';
        strongMsg.style.display = 'block';
      } else {
        strongGroup.style.opacity = '0.5';
        strongFill.style.width = '0%';

        baselineMsg.style.display = 'block';
        strongMsg.style.display = 'none';
      }
    });
  }

  // Event Listeners
  radios.forEach(radio => {
    radio.addEventListener('change', (e) => {
      updateUI(e.target.value);
    });
  });

  // Source button handling (delegated to kernel via data attribute)
  sourceBtns.forEach(btn => {
    btn.addEventListener('click', (e) => {
      // Kernel handles data-source attribute
      // No action needed here other than ensuring event bubbles if needed
    });
  });

  // Initialize
  updateUI('baseline');

})();
